using System;using System.Linq;using UnityEngine;using UnityEditor;
public static class InspectB2Slash {
 public static object Run(){var a=UnityEngine.Object.FindObjectsByType<Animator>(FindObjectsInactive.Include,FindObjectsSortMode.None).First(t=>t.name.StartsWith("Meshy_AI_lowpoly_paladin"));var g=UnityEngine.Object.Instantiate(a.gameObject);g.hideFlags=HideFlags.HideAndDontSave;var animator=g.GetComponent<Animator>();animator.enabled=false;var clip=a.runtimeAnimatorController.animationClips[0];var hand=g.GetComponentsInChildren<Transform>().First(t=>t.name=="RightHand");var skin=g.GetComponentInChildren<SkinnedMeshRenderer>();var samples=new System.Collections.Generic.List<object>();try{Vector3 previous=Vector3.zero;for(int f=0;f<=54;f++){clip.SampleAnimation(g,f/30f);if(f>0)samples.Add(new{frame=f,verticalDelta=hand.position.y-previous.y,speed=Vector3.Distance(hand.position,previous),height=hand.position.y});previous=hand.position;}var model=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/3DBattle/Boss2/Meshy_AI_symmetric_white_slash_3d_20261105_generate.fbx");return new{skinBounds=skin.sharedMesh.bounds.ToString("F5"),skinScale=skin.transform.lossyScale.ToString(),samples,slash=model.GetComponentsInChildren<MeshFilter>().Select(m=>new{m.name,bounds=m.sharedMesh.bounds.ToString("F5"),scale=m.transform.localScale.ToString(),rot=m.transform.localEulerAngles.ToString()}).ToArray()};}finally{UnityEngine.Object.DestroyImmediate(g);}}
}
